from __future__ import annotations

from typing import Annotated, Any, Literal

from pydantic import BaseModel, ConfigDict, Field
from typing_extensions import TypeAliasType


class ContractRef(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    id: str = Field(..., examples=["fenon.hand_pose.video"])
    version: str = Field(..., pattern="^[0-9]+\\.[0-9]+\\.[0-9]+$")
    schema_sha256: str = Field(..., pattern="^[0-9a-f]{64}$")


class RunError(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    code: Literal["input_unsupported", "processing_failed", "deadline_exceeded", "canceled"]
    message: str
    fix: str | None
    retryable: bool
    retry_after_s: float | None
    details: dict[str, Any]
    stage: Literal["queued", "processing_frames"] = Field(
        ..., description="The status the run was in when it stopped."
    )


RunId = TypeAliasType("RunId", Annotated[str, Field(..., pattern="^run_[0-9a-hjkmnp-tv-z]{12}$")])


class RunProgress(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    completed: int = Field(..., ge=0)
    total: int = Field(..., ge=0)
    unit: Literal["frame"]


RunStatus = TypeAliasType(
    "RunStatus", Literal["queued", "processing_frames", "succeeded", "failed", "canceled"]
)


class RunUsage(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    unit: str = Field(..., description="`second` for recorded runs.", examples=["second"])
    quantity: int = Field(..., ge=0)


Timestamp = TypeAliasType(
    "Timestamp",
    Annotated[
        str,
        Field(
            ...,
            examples=["2026-10-31T12:00:00.000Z"],
            pattern="^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{3}Z$",
        ),
    ],
)


UploadId = TypeAliasType("UploadId", Annotated[str, Field(..., pattern="^upl_[0-9a-hjkmnp-tv-z]{12}$")])


class UploadReservation(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    id: UploadId
    status: Literal["pending"]
    upload_url: str = Field(
        ...,
        description="A presigned link into the object store. Send no Authorization header.",
        repr=False,
    )
    method: Literal["PUT"]
    headers: dict[str, str] = Field(
        ...,
        description="Send exactly these with the PUT: `Content-Type`, `Content-Length` and `If-None-Match: *`.",
    )
    expires_at: Timestamp


class InputFiles(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    id: UploadId
    filename: str
    size_bytes: int = Field(..., ge=1)


class OutputFile(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    content_type: str
    url: str = Field(
        ...,
        description="A presigned download link. Send no Authorization header.",
        repr=False,
    )
    url_expires_at: Timestamp
    size_bytes: int = Field(..., ge=0)


class Run(BaseModel):
    model_config = ConfigDict(
        extra="ignore",
    )
    id: RunId
    object: Literal["run"]
    model: str
    model_version: str | None = Field(
        ...,
        description="The version the model engine ran; null until the run succeeds.",
    )
    contract: ContractRef
    status: RunStatus
    input: dict[str, Any] = Field(..., description="The input as sent.")
    input_files: dict[str, InputFiles] = Field(
        ...,
        description="The upload the input names, under the input field that names it.",
    )
    outputs_requested: list[str]
    progress: RunProgress | None
    usage_estimate: RunUsage | None
    outputs: dict[str, OutputFile] | None
    outputs_expire_at: Timestamp | None
    outputs_expired: bool
    result: dict[str, Any] | None
    usage: RunUsage | None
    error: RunError | None
    created_at: Timestamp
    started_at: Timestamp | None
    finished_at: Timestamp | None


